"use client";

import type { ComponentProps, ReactNode } from "react";
import { LoginMinimal } from "./login-minimal";

interface LoginProps extends Omit<ComponentProps<"form">, "title" | "action"> {
  title?: string;
  description?: string;
  brand?: string;
  logo?: ReactNode;
  showSocial?: boolean;
  onProviderLogin?: (provider: "google" | "github") => void;
  loading?: boolean;
  error?: string;
  forgotPasswordHref?: string;
  signupHref?: string;
  helpHref?: string;
  termsHref?: string;
  privacyHref?: string;
}

export function Login(props: LoginProps = {}) {
  return (
    <div
      data-slot="login"
      data-layout="card"
      className="@container relative isolate grid h-full w-full place-items-center overflow-hidden bg-cover bg-center bg-no-repeat p-4"
      style={{ backgroundImage: `url("/image.png")` }}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 bg-slate-950/30 backdrop-blur-[2px]"
      />
      <div className="relative z-10 w-full max-w-md border border-border bg-card text-card-foreground shadow-sm">
        <LoginMinimal {...props} />
      </div>
    </div>
  );
}

"use client";

import { useId, useState, type ComponentProps, type ReactNode } from "react";
import Image from "next/image";
import { Eye, EyeOff } from "lucide-react";
import { Google, GitHubDark } from "@ridemountainpig/svgl-react";
import { cn } from "cn";
import { Banner } from "../components/banner";
import { Button } from "../components/button";
import { Card } from "../components/card";

interface LoginProps extends Omit<ComponentProps<"form">, "title" | "action"> {
  title?: string;
  description?: string;
  brand?: string;
  logo?: ReactNode;
  showSocial?: boolean;
  onProviderLogin?: (provider: "google" | "github") => void;
  loading?: boolean;
  error?: string;
  forgotPasswordHref?: string;
  signupHref?: string;
  helpHref?: string;
  termsHref?: string;
  privacyHref?: string;
}

export function LoginMinimal({
  title = "Welcome back",
  description = "Sign in to pick up where you left off.",
  brand = "Studio",
  logo = <Image src="/logo.svg" alt={`${brand} logo`} width={40} height={40} className="size-10" />,
  showSocial = true,
  onProviderLogin,
  loading = false,
  error,
  forgotPasswordHref = "/forgot-password",
  signupHref = "/signup",
  helpHref = "/help",
  termsHref = "/terms",
  privacyHref = "/privacy",
  onSubmit,
  className,
  children,
  ...props
}: LoginProps = {}) {
  return (
    <div data-slot="login" data-layout="minimal" className="@container w-full">
      <div>
        <Card
          title=""
          description=""
          className={cn(
            "mx-auto max-w-md!",
            "border-0! bg-transparent! p-6! @sm:p-10! text-foreground shadow-none!",
          )}
        >
          {logo && <div className="mb-6">{logo}</div>}
          {title && <h2 className={"typography-section-title"}>{title}</h2>}
          {description && <p className={`mt-2 typography-body`}>{description}</p>}
          <div className="mt-8">
            <LoginForm
              {...props}
              title={title}
              showSocial={showSocial}
              onProviderLogin={onProviderLogin}
              loading={loading}
              error={error}
              forgotPasswordHref={forgotPasswordHref}
              signupHref={signupHref}
              onSubmit={onSubmit}
              className={className}
            >
              {children}
            </LoginForm>
          </div>
          {(helpHref || termsHref || privacyHref) && (
            <footer className="mt-8">
              <nav
                aria-label="Login resources"
                className="flex flex-wrap items-center justify-center gap-x-3 gap-y-2 text-xs leading-6 text-muted-foreground"
              >
                {[
                  ["Help", helpHref],
                  ["Terms", termsHref],
                  ["Privacy", privacyHref],
                ]
                  .filter(([, href]) => href)
                  .map(([label, href], index) => (
                    <span key={label} className="inline-flex items-center gap-3">
                      {index > 0 && <span aria-hidden="true">/</span>}
                      <a
                        href={href}
                        className="transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
                      >
                        {label}
                      </a>
                    </span>
                  ))}
              </nav>
            </footer>
          )}
        </Card>
      </div>
    </div>
  );
}
function LoginForm({
  title,
  showSocial,
  onProviderLogin,
  loading,
  error,
  forgotPasswordHref,
  signupHref,
  onSubmit,
  className,
  children,
  ...props
}: Readonly<LoginProps>) {
  const id = useId();
  return (
    <form
      {...props}
      aria-label={props["aria-label"] ?? title}
      className={cn("space-y-6", className)}
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit?.(event);
      }}
    >
      {error && (
        <div role="alert">
          <Banner variant="error" dismissible={false} message={error} />
        </div>
      )}
      {showSocial && (
        <div>
          <div className="grid grid-cols-2 gap-3">
            <Button
              variant="outline"
              className="px-4! font-medium!"
              disabled={loading || !onProviderLogin}
              onClick={() => onProviderLogin?.("google")}
            >
              <Google width={16} height={16} aria-hidden="true" />
              Google
            </Button>
            <Button
              variant="outline"
              className="px-4! font-medium!"
              disabled={loading || !onProviderLogin}
              onClick={() => onProviderLogin?.("github")}
            >
              <GitHubDark className="invert dark:invert-0" width={16} height={16} aria-hidden="true" />
              GitHub
            </Button>
          </div>
          <div className="my-6 flex items-center gap-3 text-xs text-muted-foreground">
            <span className="h-px flex-1 bg-border" />
            Or continue with email
            <span className="h-px flex-1 bg-border" />
          </div>
        </div>
      )}
      <div className="space-y-2">
        <label htmlFor={`${id}-email`} className="block text-sm font-medium">
          Email
        </label>
        <input
          id={`${id}-email`}
          name="email"
          type="email"
          autoComplete="email"
          placeholder="you@example.com"
          required
          disabled={loading}
          className="min-h-11 w-full border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:opacity-50"
        />
      </div>
      <PasswordField id={id} loading={loading} forgotPasswordHref={forgotPasswordHref} />
      {children}
      <Button
        type="submit"
        className="w-full px-4!"
        disabled={loading || !onSubmit}
        aria-busy={loading}
      >
        {loading ? "Signing in…" : "Sign in"}
      </Button>
      {signupHref && (
        <p className="text-center text-sm leading-6 text-muted-foreground">
          New here?{" "}
          <a
            href={signupHref}
            className="font-medium text-foreground hover:underline focus-visible:outline-2 focus-visible:outline-ring"
          >
            Create an account
          </a>
        </p>
      )}
    </form>
  );
}
function PasswordField({
  id,
  loading,
  forgotPasswordHref,
}: Readonly<{
  id: string;
  loading?: boolean;
  forgotPasswordHref?: string;
}>) {
  const [visible, setVisible] = useState(false);
  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between gap-3">
        <label htmlFor={`${id}-password`} className="text-sm font-medium">
          Password
        </label>
        {forgotPasswordHref && (
          <a
            href={forgotPasswordHref}
            className="text-xs text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
          >
            Forgot password?
          </a>
        )}
      </div>
      <div className="flex items-center border border-border bg-background focus-within:outline-2 focus-within:outline-ring">
        <input
          id={`${id}-password`}
          name="password"
          type={visible ? "text" : "password"}
          autoComplete="current-password"
          required
          disabled={loading}
          className="min-h-11 min-w-0 flex-1 bg-transparent px-3 text-sm text-foreground outline-none disabled:opacity-50"
        />
        <Button
          variant="ghost"
          className="shrink-0 px-3!"
          disabled={loading}
          aria-label={visible ? "Hide password" : "Show password"}
          aria-pressed={visible}
          onClick={() => setVisible(!visible)}
        >
          {visible ? <EyeOff size={16} aria-hidden="true" /> : <Eye size={16} aria-hidden="true" />}
        </Button>
      </div>
    </div>
  );
}

"use client";

import { memo, useState, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion } from "motion/react";
import { CircleCheck, CircleX, Info, TriangleAlert } from "lucide-react";

interface BannerProps {
  variant?: "neutral" | "info" | "success" | "warning" | "error";
  children?: ReactNode;
  message?: string;
  description?: string;
  dismissible?: boolean;
  className?: string;
}

const statusStyles = {
  neutral: "bg-neutral-500/10 text-neutral-700 dark:text-neutral-400",
  info: "bg-sky-500/10 text-sky-700 dark:text-sky-400",
  success: "bg-green-500/10 text-green-700 dark:text-green-400",
  warning: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  error: "bg-red-500/10 text-red-700 dark:text-red-400",
};

const statusIcons = {
  neutral: Info,
  info: Info,
  success: CircleCheck,
  warning: TriangleAlert,
  error: CircleX,
};

export const Banner = memo(function Banner({
  variant = "info",
  children,
  message = "A little update. A lot of possibilities. Explore what's new.",
  description,
  dismissible = true,
  className = "",
}: BannerProps = {}) {
  const Icon = statusIcons[variant];
  const reducedMotion = useReducedMotion();
  const [dismissed, setDismissed] = useState(false);

  if (dismissed) return null;

  return (
    <motion.div
      role={variant === "error" ? "alert" : "status"}
      initial={reducedMotion ? false : { opacity: 0, y: 10 }}
      whileInView={reducedMotion ? undefined : { opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.2 }}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.005 }}
      transition={{ duration: reducedMotion ? 0 : 0.2, ease: "easeOut" }}
      className={`flex items-start gap-4 rounded-xl surface-raised surface-status px-5 py-4 text-base leading-7 ${statusStyles[variant]} ${className}`}
    >
      {Icon && <Icon aria-hidden="true" className="mt-0.5 size-6 shrink-0" strokeWidth={2} />}
      <div className="min-w-0 flex-1">
        <div className="font-semibold">{children ?? message}</div>
        {description && <p className="mt-1 text-sm leading-6 opacity-90">{description}</p>}
      </div>
      {dismissible && (
        <button
          type="button"
          aria-label="Dismiss banner"
          onClick={() => setDismissed(true)}
          className="flex size-9 shrink-0 items-center justify-center hover:bg-black/10 focus-visible:outline-2 focus-visible:outline-current"
        >
          <span aria-hidden="true">×</span>
        </button>
      )}
    </motion.div>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});

import { memo, type ComponentProps, type ReactNode } from "react";
import { cn } from "cn";

// Legacy content props remain supported for existing consumers.
const cardSizes = {
  sm: "gap-4 px-4 py-4",
  md: "gap-6 px-6 py-6",
} as const;

type CardProps = {
  size?: keyof typeof cardSizes;
  title?: string;
  description?: string;
  footer?: ReactNode;
} & (
  | ({ as?: "article" } & Omit<ComponentProps<"article">, "title">)
  | ({ as: "a" } & Omit<ComponentProps<"a">, "title">)
);

const Card = memo(function Card({
  title,
  description,
  children,
  footer,
  className,
  size = "md",
  ...props
}: CardProps) {
  const hasLegacyContent = Boolean(title || description || footer);
  const classes = cn(
    "group/card flex w-full max-w-sm flex-col rounded-lg surface-raised text-base leading-7",
    "outline-ring focus-visible:outline-[length:var(--focus-ring-width,2px)] focus-visible:outline-offset-[var(--focus-ring-offset,2px)]",
    "[a&]:transition-colors [a&]:duration-[var(--duration-fast,150ms)] [a&]:ease-out [a&]:hover:[--surface-bottom:var(--muted)] motion-reduce:transition-none",
    cardSizes[size],
    className,
  );
  const content = (
    <>
      {(title || description) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
      )}
      {hasLegacyContent ? children && <CardContent>{children}</CardContent> : children}
      {footer && <CardFooter>{footer}</CardFooter>}
    </>
  );
  if (props.as === "a") {
    const { as: Tag, ...anchorProps } = props;
    return (
      <Tag data-slot="card" data-size={size} className={classes} {...anchorProps}>
        {content}
      </Tag>
    );
  }
  const { as: Tag = "article", ...articleProps } = props;
  return (
    <Tag data-slot="card" data-size={size} className={classes} {...articleProps}>
      {content}
    </Tag>
  );
});

const CardHeader = memo(function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="card-header"
      className={cn(
        "grid auto-rows-min items-start gap-x-4 gap-y-2 has-[[data-slot=card-action]]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
});

const CardTitle = memo(function CardTitle({ className, ...props }: ComponentProps<"h3">) {
  return (
    <h3 data-slot="card-title" className={cn("typography-section-title", className)} {...props} />
  );
});

const CardDescription = memo(function CardDescription({
  className,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="card-description"
      className={cn("col-start-1", "typography-body", className)}
      {...props}
    />
  );
});

const CardAction = memo(function CardAction({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
});

const CardContent = memo(function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />;
});

const CardFooter = memo(function CardFooter({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      data-slot="card-footer"
      className={cn("flex items-center border-t border-border pt-4", className)}
      {...props}
    />
  );
});

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };
